import{_ as e,o as t,c as a,ai as r}from"./chunks/framework.BBSijY9B.js";const p=JSON.parse('{"title":"CamoFox：给 Agent 的隐蔽浏览器，快照比 HTML 小约 90%","description":"","frontmatter":{"date":"2026-10-25T00:00:00.000Z","title":"CamoFox：给 Agent 的隐蔽浏览器，快照比 HTML 小约 90%","summary":"jo-inc/camofox-browser（约 1.2 万星，MIT）把 Camoufox 包成 REST 服务；无障碍树快照 + 元素引用，适合当 Agent 浏览后端。我们 10/25 在 Linux 上装通并跑通 example.com 快照。","category":"好项目","tags":["GitHub 高星项目","AI 工具","浏览器自动化","实测"],"sources":[{"url":"https://github.com/jo-inc/camofox-browser","author":"jo-inc/camofox-browser（GitHub）","platform":"GitHub"},{"url":"https://camoufox.com","author":"Camoufox 官方","platform":"官方站点"},{"url":"https://x.com/0xrux/status/2113957254307196963","author":"@0xrux","platform":"X"}],"updates":[{"link":"/cases/camofox","title":"新增案例：CamoFox 安装、快照用法与避坑（含 2026-10-25 实测）"},{"link":"/cases/ai","title":"AI 工具分区：补充 CamoFox"},{"link":"/resources/?tab=projects","title":"资源导航 · 开源项目：新增 CamoFox"}],"wordCount":368,"readingTime":1,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"CamoFox：给 Agent 的隐蔽浏览器，快照比 HTML 小约 90% | 王宇宙 | WANGXXXL"}],["meta",{"property":"og:description","content":"jo-inc/camofox-browser（约 1.2 万星，MIT）把 Camoufox 包成 REST 服务；无障碍树快照 + 元素引用，适合当 Agent 浏览后端。我们 10/25 在 Linux 上装通并跑通 example.com 快照。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/daily/2026-10-25-camofox-browser"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/daily-2026-10-25-camofox-browser-f29d02338c.png"}],["meta",{"property":"og:image:alt","content":"CamoFox：给 Agent 的隐蔽浏览器，快照比 HTML 小约 90% · 王宇宙 | WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"CamoFox：给 Agent 的隐蔽浏览器，快照比 HTML 小约 90% | 王宇宙 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"jo-inc/camofox-browser（约 1.2 万星，MIT）把 Camoufox 包成 REST 服务；无障碍树快照 + 元素引用，适合当 Agent 浏览后端。我们 10/25 在 Linux 上装通并跑通 example.com 快照。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/daily-2026-10-25-camofox-browser-f29d02338c.png"}],["meta",{"name":"twitter:image:alt","content":"CamoFox：给 Agent 的隐蔽浏览器，快照比 HTML 小约 90% · 王宇宙 | WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/daily/2026-10-25-camofox-browser"}]]},"headers":[],"relativePath":"daily/2026-10-25-camofox-browser.md","filePath":"daily/2026-10-25-camofox-browser.md","lastUpdated":1792858790000}'),c={name:"daily/2026-10-25-camofox-browser.md"};function n(s,o,m,i,l,x){return t(),a("div",null,[...o[0]||(o[0]=[r('<h1 id="camofox-给-agent-的隐蔽浏览器-快照比-html-小约-90" tabindex="-1">CamoFox：给 Agent 的隐蔽浏览器，快照比 HTML 小约 90% <a class="header-anchor" href="#camofox-给-agent-的隐蔽浏览器-快照比-html-小约-90" aria-label="Permalink to &quot;CamoFox：给 Agent 的隐蔽浏览器，快照比 HTML 小约 90%&quot;">​</a></h1><p>普通 Playwright / 无头 Chrome 容易被指纹和机器人检测拦住；整页 HTML 塞进模型又贵又吵。<a href="https://github.com/jo-inc/camofox-browser" target="_blank" rel="noopener noreferrer">CamoFox</a>（jo-inc，MIT，截至 2026-10-25 约 <strong>11,892</strong> star）把 <a href="https://camoufox.com" target="_blank" rel="noopener noreferrer">Camoufox</a>（C++ 层指纹伪装的 Firefox）包成面向 Agent 的 REST 服务：<strong>无障碍树快照 + 稳定元素引用（e1、e2…）</strong>。官方写明快照大约比原始 HTML 小 <strong>90%</strong>。</p><p>X 上 <a href="https://x.com/0xrux/status/2113957254307196963" target="_blank" rel="noopener noreferrer">@0xrux</a> 也提到过它；步骤以 GitHub README 为准。</p><h2 id="三步上手" tabindex="-1">三步上手 <a class="header-anchor" href="#三步上手" aria-label="Permalink to &quot;三步上手&quot;">​</a></h2><div class="steps"><ol><li><strong>Node ≥ 22</strong>，然后：<code>git clone https://github.com/jo-inc/camofox-browser &amp;&amp; cd camofox-browser &amp;&amp; npm install --omit=dev &amp;&amp; npm start</code> → <code>http://127.0.0.1:9377</code>（第一次会下载约几百 MB 的浏览器包）。</li><li><strong>健康检查</strong>：<code>curl -s http://127.0.0.1:9377/health</code>，看到 <code>ok: true</code> 和 <code>engine: camoufox</code> 再往下。</li><li><strong>开标签拿快照</strong>：<code>POST /tabs</code> 带 <code>userId</code>、<code>sessionKey</code>、<code>url</code>；再 <code>GET /tabs/:tabId/snapshot?userId=...</code>。完整命令、Cookie、代理和避坑见 <a href="/cases/camofox">/cases/camofox</a>。</li></ol></div><h2 id="wangxxxl-实测于-2026-10-25-utc-8" tabindex="-1">WANGXXXL 实测于 2026-10-25（UTC+8） <a class="header-anchor" href="#wangxxxl-实测于-2026-10-25-utc-8" aria-label="Permalink to &quot;WANGXXXL 实测于 2026-10-25（UTC+8）&quot;">​</a></h2><ul><li>环境：Linux，Node 22.20.0，包版本 1.18.1。</li><li><code>GET /health</code> 正常；打开 <code>https://example.com</code> 返回 <code>httpStatus: 200</code>；快照约 <strong>1052</strong> 字符，带可点击 <code>[e1]</code>。</li><li>未测：真实 Cloudflare 挑战通过率、Cookie 导入、Docker。</li></ul><h2 id="注意" tabindex="-1">注意 <a class="header-anchor" href="#注意" aria-label="Permalink to &quot;注意&quot;">​</a></h2><ul><li>Cookie 导入默认关闭，要设 <code>CAMOFOX_API_KEY</code>。</li><li>Issues 里常见原生内存上涨和偶发导航挂起：控制会话数，用完关掉 session。</li><li>只用于你有权访问的站点；能绕过检测 ≠ 可以违规抓站。</li></ul><p>完整安装、API 示例和避坑：<a href="/cases/camofox">CamoFox 案例页</a>。</p>',10)])])}const u=e(c,[["render",n]]);export{p as __pageData,u as default};
